-- Run only after reviewed 120000 apply, in an explicitly selected local test DB.
-- Supply two existing eligible synthetic members via SET native_ai.fixture_owner
-- and SET native_ai.fixture_other_owner. This script never calls a provider or wallet RPC.
BEGIN;
SET LOCAL lock_timeout='3s';
SET LOCAL statement_timeout='30s';
CREATE TEMP TABLE native_ai_fixture_results(name text PRIMARY KEY,passed boolean NOT NULL);
CREATE FUNCTION pg_temp.ai_assert(p boolean,label text) RETURNS void LANGUAGE plpgsql AS $$BEGIN IF p IS NOT TRUE THEN RAISE EXCEPTION 'FIXTURE_ASSERTION_FAILED: %',label;END IF;INSERT INTO native_ai_fixture_results VALUES(label,true);END$$;
CREATE FUNCTION pg_temp.ai_snapshot(p_id uuid,p_amount text DEFAULT '1') RETURNS jsonb LANGUAGE plpgsql AS $$DECLARE wire jsonb;BEGIN
 wire:=jsonb_build_object('client_request_id','native_'||p_id::text||'_0','modelId','pm_native_fixture','agentId','__free_chat__','model_overridden',true,'stream',true,'max_reply_tokens',128,'max_context_rounds',0,'max_context_tokens',1024,'messages',jsonb_build_array(jsonb_build_object('role','user','content','fixture only')));
 RETURN jsonb_build_object('version','native-ai-action.v1','kind','plan_text','args',jsonb_build_object('modelId','pm_native_fixture','prompt','fixture only','contextSnapshotHash',repeat('a',64),'maxReplyTokens',128,'maxContextRounds',0,'maxContextTokens',1024),'sourceActionId',NULL,'resources','[]'::jsonb,'quote',jsonb_build_object('unit','credits','quotedAmount',p_amount,'maxAmount',p_amount,'priceHash',repeat('b',64),'expiresAt',to_char(clock_timestamp()+interval '10 minutes','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),'surface','native-agent-text','permissionRevision','fixture:1','slots',jsonb_build_array(jsonb_build_object('slot',0,'consumer','main_llm','requestKey','native_'||p_id::text||'_0','wireRequest',wire,'wireRequestHash',public.native_ai_hash(wire))));
END$$;
DO $$<<fixture>>DECLARE
 actor text:=current_setting('native_ai.fixture_owner',true);other_actor text:=current_setting('native_ai.fixture_other_owner',true);
 batch uuid:=gen_random_uuid();item uuid:=gen_random_uuid();action_id uuid:=gen_random_uuid();second_id uuid:=gen_random_uuid();manifest_action uuid:=gen_random_uuid();task_id uuid:=gen_random_uuid();draft_id uuid;account_id uuid;snap jsonb;req jsonb;result jsonb;replayed jsonb;claim jsonb;admit jsonb;wire jsonb;before_wallet jsonb;after_wallet jsonb;before_publish bigint;did_reject boolean;v_revision integer;v_unit text;
BEGIN
 IF actor IS NULL OR other_actor IS NULL OR actor=other_actor THEN RAISE EXCEPTION 'EXPLICIT_TWO_SYNTHETIC_MEMBER_IDS_REQUIRED';END IF;
 PERFORM public.pub_assert_actor(actor);PERFORM public.pub_assert_actor(other_actor);
 INSERT INTO public.pub_native_agent_tasks(id,owner_id,title) VALUES(task_id,actor,'action list owner fixture');
 result:=public.read_native_ai_atomic(actor,jsonb_build_object('action','actions-for-task','taskId',task_id,'page',1,'pageSize',30));PERFORM pg_temp.ai_assert(result->'items'='[]'::jsonb AND result->>'total'='0','owned task can read an exact empty action page');
 did_reject:=false;BEGIN PERFORM public.read_native_ai_atomic(other_actor,jsonb_build_object('action','actions-for-task','taskId',task_id,'page',1,'pageSize',30));EXCEPTION WHEN OTHERS THEN did_reject:=SQLERRM='NATIVE_AI_NOT_FOUND';END;PERFORM pg_temp.ai_assert(did_reject,'foreign owner cannot list task actions');
 SELECT jsonb_build_object('credits',credits,'cash',cash_balance) INTO before_wallet FROM public.users WHERE id=actor;
 PERFORM pg_temp.ai_assert(NOT has_table_privilege('service_role','public.pub_native_ai_actions','INSERT') AND NOT has_table_privilege('service_role','public.pub_native_ai_actions','UPDATE'),'service role cannot write action rows');
 PERFORM pg_temp.ai_assert(has_function_privilege('service_role','public.mutate_native_ai_atomic(text,jsonb)','EXECUTE') AND NOT has_function_privilege('authenticated','public.mutate_native_ai_atomic(text,jsonb)','EXECUTE'),'RPC has exact service-only execute grant');
 PERFORM pg_temp.ai_assert(NOT has_function_privilege('service_role','public.native_ai_insert_action(text,uuid,jsonb,jsonb,text)','EXECUTE'),'internal insert helper is not API executable');
 PERFORM pg_temp.ai_assert(public.native_ai_no_credentials(jsonb_build_object('tokenBilling',jsonb_build_object('maxChargeYuan',1.2,'priceVersion','video_token_sale.v1:{"720p:no_reference_video":12,"720p:reference_video":18}'))) AND NOT public.native_ai_no_credentials(jsonb_build_object('tokenBilling',jsonb_build_object('maxChargeYuan',1.2,'priceVersion','video_token_sale.v1:{"720p:no_reference_video":12,"720p:reference_video":18}','token','forged'))) AND NOT public.native_ai_no_credentials('{"otherToken":"forged"}'),'tokenBilling permits only its exact public price contract');
 PERFORM pg_temp.ai_assert(public.native_ai_hash('{"z":[{"b":2,"a":"中"}],"a":"0.000001","quote":{"maxAmount":"1","quotedAmount":"0.6"}}')=encode(sha256(convert_to('{"a":"0.000001","quote":{"maxAmount":"1","quotedAmount":"0.6"},"z":[{"a":"中","b":2}]}','UTF8')),'hex'),'SQL canonical agrees with independent JS fixture text');
 snap:=pg_temp.ai_snapshot(action_id);
 req:=jsonb_build_object('action','prepare-batch','requestKey','fixture.prepare.'||batch::text,'batchId',batch,'snapshot',jsonb_build_object('version','native-ai-batch.v1','mode','image_text','collectionId',NULL,'prompt','fixture only','captionPrompt','','quantity',1,'imageCount',1,'plannerModelId','pm_native_fixture','generationModelId','pm_native_fixture','options',jsonb_build_object('aspectRatio','1:1','resolution','1k','duration',NULL),'platforms','[]'::jsonb,'budget',jsonb_build_object('credits','2','CNY','1'),'savePolicy','confirm_resolved_drafts'),'items',jsonb_build_array(jsonb_build_object('id',item,'ordinal',0,'initialAction',jsonb_build_object('id',action_id,'snapshot',snap,'actionHash',public.native_ai_hash(snap)))));
 result:=public.mutate_native_ai_atomic(actor,req);replayed:=public.mutate_native_ai_atomic(actor,req);
 PERFORM pg_temp.ai_assert(result=replayed AND jsonb_array_length(result->'items')=1 AND result->'actions'->0->>'state'='proposed','prepare batch immutable replay');
 did_reject:=false;BEGIN PERFORM public.mutate_native_ai_atomic(actor,jsonb_set(req,'{snapshot,prompt}','"changed"'));EXCEPTION WHEN OTHERS THEN did_reject:=SQLERRM='NATIVE_AI_IDEMPOTENCY_CONFLICT';END;PERFORM pg_temp.ai_assert(did_reject,'same mutation key cannot replace frozen input');
 did_reject:=false;BEGIN PERFORM public.read_native_ai_atomic(other_actor,jsonb_build_object('action','action','actionId',action_id));EXCEPTION WHEN OTHERS THEN did_reject:=SQLERRM='NATIVE_AI_NOT_FOUND';END;PERFORM pg_temp.ai_assert(did_reject,'foreign member cannot read action UUID');
 result:=public.mutate_native_ai_atomic(actor,jsonb_build_object('action','decide','requestKey','fixture.approve.'||action_id::text,'proposalId',action_id,'expectedRevision',1,'decision','approve'));
 PERFORM pg_temp.ai_assert(result->'action'->>'state'='approved','approve accepts only frozen snapshot');
 did_reject:=false;BEGIN PERFORM public.mutate_native_ai_atomic(actor,jsonb_build_object('action','decide','requestKey','fixture.forged.'||action_id::text,'proposalId',action_id,'expectedRevision',2,'decision','approve','args','{}'::jsonb));EXCEPTION WHEN OTHERS THEN did_reject:=true;END;PERFORM pg_temp.ai_assert(did_reject,'decision cannot replace arguments');
 claim:=jsonb_build_object('action','claim-dispatch','requestKey','fixture.claim.'||action_id::text,'actionId',action_id,'expectedRevision',2,'slot',0);
 result:=public.mutate_native_ai_atomic(actor,claim);replayed:=public.mutate_native_ai_atomic(actor,claim);
 PERFORM pg_temp.ai_assert(result->>'shouldDispatch'='true' AND replayed->>'shouldDispatch'='false' AND result->>'dispatchId'=replayed->>'dispatchId','one durable dispatch claim and replay suppresses permit');
 admit:=jsonb_build_object('action','admit-consumer','requestKey','fixture.admit.'||action_id::text,'actionId',action_id,'slot',0,'dispatchId',result->>'dispatchId','wireRequestHash',snap->'slots'->0->>'wireRequestHash','consumer','main_llm','modelPublicId','pm_native_fixture','surface','native-agent-text','priceHash',repeat('b',64),'reservationAmount','0.5','unit','credits');
 result:=public.mutate_native_ai_atomic(actor,admit);replayed:=public.mutate_native_ai_atomic(actor,admit);
 PERFORM pg_temp.ai_assert(result->'admission'->>'newlyAdmitted'='true' AND replayed->'admission'->>'newlyAdmitted'='false','consumer admission replay never admits twice');
 result:=public.mutate_native_ai_atomic(actor,jsonb_build_object('action','reconcile','requestKey','fixture.observe.'||action_id::text,'actionId',action_id,'slot',0));
 PERFORM pg_temp.ai_assert(result->'slot'->>'state'='unknown' AND result->'slot'->'receipt'='null'::jsonb,'missing upstream record is unknown');
 v_revision:=(result->'action'->>'revision')::integer;
 result:=public.mutate_native_ai_atomic(actor,jsonb_build_object('action','claim-dispatch','requestKey','fixture.reclaim.'||action_id::text,'actionId',action_id,'expectedRevision',v_revision,'slot',0));
 PERFORM pg_temp.ai_assert(result->>'shouldDispatch'='false','missing upstream record never restores dispatch');
 PERFORM pg_temp.ai_assert((SELECT reservation_amount='0.5' AND admitted_at IS NOT NULL FROM public.pub_native_ai_slots x WHERE x.action_id=fixture.action_id AND x.owner_id=actor),'unknown retains its admitted budget');
 snap:=pg_temp.ai_snapshot(second_id,'2');
 result:=public.mutate_native_ai_atomic(actor,jsonb_build_object('action','prepare-action','requestKey','fixture.second.'||second_id::text,'actionId',second_id,'scope',jsonb_build_object('kind','batch','batchId',batch,'itemId',item),'snapshot',snap,'actionHash',public.native_ai_hash(snap)));
 result:=public.mutate_native_ai_atomic(actor,jsonb_build_object('action','decide','requestKey','fixture.second.approve.'||second_id::text,'proposalId',second_id,'expectedRevision',1,'decision','approve'));
 result:=public.mutate_native_ai_atomic(actor,jsonb_build_object('action','claim-dispatch','requestKey','fixture.second.claim.'||second_id::text,'actionId',second_id,'expectedRevision',2,'slot',0));
 did_reject:=false;BEGIN PERFORM public.mutate_native_ai_atomic(actor,jsonb_build_object('action','admit-consumer','requestKey','fixture.second.admit.'||second_id::text,'actionId',second_id,'slot',0,'dispatchId',result->>'dispatchId','wireRequestHash',snap->'slots'->0->>'wireRequestHash','consumer','main_llm','modelPublicId','pm_native_fixture','surface','native-agent-text','priceHash',repeat('b',64),'reservationAmount','1.6','unit','credits'));EXCEPTION WHEN OTHERS THEN did_reject:=SQLERRM='NATIVE_AI_BUDGET_EXCEEDED';END;PERFORM pg_temp.ai_assert(did_reject,'batch budget includes prior unknown admissions');
 result:=public.mutate_publish_v2_atomic(actor,jsonb_build_object('action','save-draft','expectedRevision',0,'draft',jsonb_build_object('schemaVersion',2,'collectionId',NULL,'contentType','image','title','local confirmation fixture','body','','topics','[]'::jsonb,'media','[]'::jsonb,'targets','[]'::jsonb)));draft_id:=(result->'row'->>'id')::uuid;
 result:=public.save_publish_account_atomic(actor,'xhs','fixture:'||manifest_action::text,'synthetic browser-reported fixture',NULL);account_id:=(result->>'id')::uuid;
 wire:=jsonb_build_object('requestKey','native_'||manifest_action::text||'_0');
 snap:=jsonb_build_object('version','native-ai-action.v1','kind','propose_publish','args',jsonb_build_object('draftId',draft_id,'expectedRevision',1,'expectedMetadataRevision',0,'browserAccountIds',jsonb_build_array(account_id),'officialBindingIds','[]'::jsonb,'scheduledAt',NULL),'sourceActionId',NULL,'resources',jsonb_build_array(jsonb_build_object('kind','draft','id',draft_id,'revision',1),jsonb_build_object('kind','account','id',account_id,'revision',0)),'quote',jsonb_build_object('unit','metadata_write','quotedAmount','0','maxAmount','0','priceHash',repeat('c',64),'expiresAt',to_char(clock_timestamp()+interval '10 minutes','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),'surface',NULL,'permissionRevision','fixture:1','slots',jsonb_build_array(jsonb_build_object('slot',0,'consumer','publish_manifest','requestKey','native_'||manifest_action::text||'_0','wireRequest',wire,'wireRequestHash',public.native_ai_hash(wire))));
 result:=public.mutate_native_ai_atomic(actor,jsonb_build_object('action','prepare-action','requestKey','fixture.manifest.prepare.'||manifest_action::text,'actionId',manifest_action,'scope',jsonb_build_object('kind','batch','batchId',batch,'itemId',item),'snapshot',snap,'actionHash',public.native_ai_hash(snap)));
 result:=public.mutate_native_ai_atomic(actor,jsonb_build_object('action','decide','requestKey','fixture.manifest.approve.'||manifest_action::text,'proposalId',manifest_action,'expectedRevision',1,'decision','approve'));
 result:=public.mutate_native_ai_atomic(actor,jsonb_build_object('action','claim-dispatch','requestKey','fixture.manifest.claim.'||manifest_action::text,'actionId',manifest_action,'expectedRevision',2,'slot',0));
 SELECT (SELECT count(*) FROM public.pub2_attempts WHERE user_id=actor)+(SELECT count(*) FROM public.pub3_operations WHERE owner_id=actor) INTO before_publish;
 result:=public.mutate_native_ai_atomic(actor,jsonb_build_object('action','reconcile','requestKey','fixture.manifest.finish.'||manifest_action::text,'actionId',manifest_action,'slot',0));
 PERFORM pg_temp.ai_assert(result->'slot'->>'state'='succeeded' AND result->'slot'->'receipt'->'resultRefs'->0->>'kind'='manifest' AND EXISTS(SELECT 1 FROM public.pub_native_ai_publish_manifests m WHERE m.owner_id=actor AND m.id=manifest_action AND m.snapshot->>'state'='awaiting_user_confirmation'),'publish tool creates a real local confirmation manifest');
 PERFORM pg_temp.ai_assert((SELECT count(*) FROM public.pub2_attempts WHERE user_id=actor)+(SELECT count(*) FROM public.pub3_operations WHERE owner_id=actor)=before_publish,'local confirmation does not create a publish attempt');
 did_reject:=false;BEGIN UPDATE public.pub_native_ai_actions SET snapshot='{}'::jsonb WHERE id=fixture.action_id AND owner_id=actor;EXCEPTION WHEN OTHERS THEN did_reject:=SQLERRM='NATIVE_AI_HISTORY_IMMUTABLE';END;PERFORM pg_temp.ai_assert(did_reject,'action immutable snapshot trigger');
 did_reject:=false;BEGIN UPDATE public.pub_native_ai_events SET safe_payload='{}'::jsonb WHERE owner_id=actor;EXCEPTION WHEN OTHERS THEN did_reject:=SQLERRM='NATIVE_AI_HISTORY_IMMUTABLE';END;PERFORM pg_temp.ai_assert(did_reject,'events are append only');
 SELECT jsonb_build_object('credits',credits,'cash',cash_balance) INTO after_wallet FROM public.users WHERE id=actor;
 PERFORM pg_temp.ai_assert(before_wallet=after_wallet,'orchestration does not change the wallet');
END$$;
SELECT name,passed FROM native_ai_fixture_results ORDER BY name;
ROLLBACK;
